public str getName()
{
    return fieldPName(CustCollectionsContact, ContactPersonId);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    CustCollectionsContact custCollectionsContact;

    while select custCollectionsContact
        group by ContactPersonId
    {
        if (! ret.in(custCollectionsContact.ContactPersonId))
        {
            ret.add(custCollectionsContact.ContactPersonId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
